# src/thumbnail/asset_selector.py
# Phase 2H / Phase 4 — Strict 4-Priority Zero-Cost Thumbnail Asset Selector
#
# Selection Priority Order:
#   Priority 1: Approved deity-specific artwork from local indexed repository.
#   Priority 2: Genuine matching deity images generated by existing visual pipeline.
#   Priority 3: Suitable frames extracted from the current video's visual assets.
#   Priority 4: Pollinations anonymous endpoint (optional fallback, fail-fast on 402/429).
#
# If all options fail: Halts with NoSuitableThumbnailAssetError.
# Anti-Cross-Deity Enforcement: Strictly prohibits selecting unrelated avatars or deities.

from __future__ import annotations

import os
import json
from pathlib import Path
from typing import Optional, Any
from dataclasses import dataclass

from src.thumbnail.asset_index import (
    DeityAssetIndex,
    ThumbnailAssetRecord,
    resolve_deity_and_avatar,
)
from src.thumbnail.frame_extractor import extract_candidate_frames, is_frame_suitable
from src.thumbnail.providers.pollinations import (
    PollinationsProvider,
    PollinationsError,
    build_thumbnail_background_prompt,
)


class NoSuitableThumbnailAssetError(RuntimeError):
    """Raised when no approved or verified asset is found for the requested deity/avatar across all priority levels."""
    pass


@dataclass
class SelectedThumbnailAsset:
    asset_path: str
    priority_level: int           # 1, 2, 3, or 4
    priority_name: str            # "APPROVED_LOCAL_ARTWORK", "PIPELINE_VISUAL_ASSET", "EXTRACTED_VIDEO_FRAME", "POLLINATIONS_FREE_FALLBACK"
    deity: str
    avatar: Optional[str]
    verification_status: str      # "VERIFIED", "PROVENANCE_MATCHED", "QUALITY_VERIFIED"
    selection_reason: str
    quality_score: float
    metadata: dict[str, Any]


class ThumbnailAssetSelector:
    """
    Implements the 4-priority zero-cost selection chain.
    """

    def __init__(self, asset_index: Optional[DeityAssetIndex] = None):
        self.asset_index = asset_index or DeityAssetIndex()

    def select_thumbnail_asset(
        self,
        topic: str,
        deity_hint: Optional[str] = None,
        avatar_hint: Optional[str] = None,
        visual_map_path: Optional[Path] = None,
        video_path: Optional[Path] = None,
        allow_pollinations_fallback: bool = True,
        pollinations_timeout: int = 15,
        temp_dir: Optional[Path] = None,
    ) -> SelectedThumbnailAsset:
        """
        Executes selection priority chain:
          1. Approved deity/avatar-specific repository artwork.
          2. Genuine matching deity images generated by visual pipeline.
          3. Suitable frames extracted from video visual assets.
          4. Anonymous Pollinations generation (if available & free).
          5. Raise NoSuitableThumbnailAssetError if all fail.
        """
        # Resolve canonical deity and avatar
        resolved_deity, resolved_avatar = resolve_deity_and_avatar(
            f"{topic} {deity_hint or ''} {avatar_hint or ''}"
        )
        deity = resolved_deity or (deity_hint or "").lower() or "lord_shiva"
        avatar = resolved_avatar or (avatar_hint.lower() if avatar_hint else None)

        audit_trail: list[str] = []

        # ── Priority 1: Approved Deity-Specific Artwork ────────────────────────
        approved_assets = self.asset_index.find_approved_assets(deity=deity, avatar=avatar)
        if approved_assets:
            best = approved_assets[0]
            audit_trail.append(f"Priority 1 SUCCESS: Found {len(approved_assets)} approved assets for {deity} (avatar={avatar}). Selected {best.asset_id}.")
            return SelectedThumbnailAsset(
                asset_path=best.file_path,
                priority_level=1,
                priority_name="APPROVED_LOCAL_ARTWORK",
                deity=deity,
                avatar=avatar,
                verification_status="VERIFIED",
                selection_reason=f"Approved local artwork {best.asset_id} matching deity '{deity}' and avatar '{avatar}'",
                quality_score=best.quality_score,
                metadata={"asset_record": best.to_dict(), "audit_trail": audit_trail},
            )
        else:
            audit_trail.append(f"Priority 1 SKIPPED: No approved local artwork for deity '{deity}' with avatar '{avatar}'.")

        # ── Priority 2: Genuine Matching Deity Images from Visual Pipeline ─────
        if visual_map_path and Path(visual_map_path).exists():
            vmap_asset = self._check_visual_map(visual_map_path, deity, avatar)
            if vmap_asset:
                audit_trail.append(f"Priority 2 SUCCESS: Visual map scene matches {deity} (avatar={avatar}): {vmap_asset}.")
                return SelectedThumbnailAsset(
                    asset_path=str(vmap_asset).replace("\\", "/"),
                    priority_level=2,
                    priority_name="PIPELINE_VISUAL_ASSET",
                    deity=deity,
                    avatar=avatar,
                    verification_status="PROVENANCE_MATCHED",
                    selection_reason=f"Pipeline visual scene matching deity '{deity}' and avatar '{avatar}'",
                    quality_score=75.0,
                    metadata={"visual_map_path": str(visual_map_path), "audit_trail": audit_trail},
                )
            else:
                audit_trail.append(f"Priority 2 SKIPPED: Visual map contains no verified matching scene for avatar '{avatar}'.")
        else:
            audit_trail.append("Priority 2 SKIPPED: No visual_map.json provided or file missing.")

        # ── Priority 3: Suitable Frames Extracted from Video Assets ────────────
        if video_path and Path(video_path).exists():
            frame_dir = (temp_dir or Path("data/thumbnails/frames")) / "extracted"
            scene_identities = []
            if visual_map_path and Path(visual_map_path).exists():
                try:
                    with open(visual_map_path, "r", encoding="utf-8") as f:
                        vdata = json.load(f)
                    scene_identities = vdata.get("visual_scenes", [])
                except Exception:
                    scene_identities = []

            extracted = extract_candidate_frames(
                video_path=Path(video_path),
                output_dir=frame_dir,
                deity=deity,
                avatar=avatar,
                source_verified=False,
                scene_identities=scene_identities,
            )

            # Strict Identity Guard: ONLY frames with QUALITY_VERIFIED + DEITY_VERIFIED qualify!
            eligible_frames = [
                f for f in extracted
                if f.get("quality_status") == "QUALITY_VERIFIED" and f.get("identity_status") == "DEITY_VERIFIED"
            ]

            if eligible_frames:
                best_frame = eligible_frames[0]
                audit_trail.append(f"Priority 3 SUCCESS: Extracted DEITY_VERIFIED frame at {best_frame['timestamp_seconds']}s from verified video.")
                return SelectedThumbnailAsset(
                    asset_path=best_frame["frame_path"],
                    priority_level=3,
                    priority_name="EXTRACTED_VIDEO_FRAME",
                    deity=deity,
                    avatar=avatar,
                    verification_status="DEITY_VERIFIED",
                    selection_reason=f"Extracted high-quality frame from verified video at {best_frame['timestamp_seconds']}s",
                    quality_score=70.0,
                    metadata={"frame_data": best_frame, "audit_trail": audit_trail},
                )
            else:
                mismatch_count = sum(1 for f in extracted if f.get("identity_status") == "DEITY_MISMATCH")
                unver_count = sum(1 for f in extracted if f.get("identity_status") == "DEITY_UNVERIFIED")
                audit_trail.append(
                    f"Priority 3 SKIPPED: Extracted frames failed identity verification "
                    f"({mismatch_count} DEITY_MISMATCH, {unver_count} DEITY_UNVERIFIED for avatar '{avatar}')."
                )
        else:
            audit_trail.append("Priority 3 SKIPPED: No video_short.mp4 provided or file missing.")

        # ── Priority 4: Pollinations Anonymous Fallback ────────────────────────
        if allow_pollinations_fallback:
            poll_bg = self._attempt_pollinations_fallback(
                topic=topic,
                deity=deity,
                avatar=avatar,
                timeout=pollinations_timeout,
                temp_dir=temp_dir or Path("data/thumbnails/backgrounds"),
            )
            if poll_bg:
                audit_trail.append(f"Priority 4 SUCCESS: Fetched background via anonymous Pollinations endpoint.")
                return SelectedThumbnailAsset(
                    asset_path=str(poll_bg).replace("\\", "/"),
                    priority_level=4,
                    priority_name="POLLINATIONS_FREE_FALLBACK",
                    deity=deity,
                    avatar=avatar,
                    verification_status="ANONYMOUS_GENERATION",
                    selection_reason=f"Anonymous Pollinations AI generation fallback for {deity}",
                    quality_score=60.0,
                    metadata={"provider": "pollinations_anonymous", "audit_trail": audit_trail},
                )
            else:
                audit_trail.append("Priority 4 FAILED: Pollinations free endpoint unavailable, rate-limited (402/429), or timed out.")
        else:
            audit_trail.append("Priority 4 SKIPPED: Pollinations fallback disabled.")

        # ── All Options Failed: Halts Cleanly ─────────────────────────────────
        err_msg = (
            f"❌ Zero-Cost Thumbnail Generation Failed: No verified or suitable asset found for "
            f"deity '{deity}' (avatar='{avatar}').\n"
            f"Audit Trail:\n" + "\n".join(f"  - {line}" for line in audit_trail) + "\n"
            f"Refusing to substitute unrelated deity artwork."
        )
        raise NoSuitableThumbnailAssetError(err_msg)

    def _check_visual_map(self, vmap_path: Path, deity: str, avatar: Optional[str]) -> Optional[Path]:
        """
        Inspects visual_map.json scenes. Returns image file path ONLY if scene prompt and image
        genuinely match the requested avatar/deity with verified provenance.
        Rejects repository files that are unapproved or mismatched for the avatar.
        """
        try:
            with open(vmap_path, "r", encoding="utf-8") as f:
                data = json.load(f)

            scenes = data.get("visual_scenes", [])
            for sc in scenes:
                prompt = (sc.get("visual_prompt") or "").lower()
                img_f = sc.get("image_file")
                source = sc.get("source", "")
                if not img_f or not Path(img_f).exists():
                    continue

                # If an avatar was requested, verify that the scene specifically targets this avatar
                if avatar:
                    sc_av = sc.get("avatar")
                    if sc_av and sc_av != avatar:
                        continue
                    if avatar.lower() not in prompt:
                        # Cross-deity or cross-avatar scene (e.g. Kurma scene in Varaha video) -> REJECT
                        continue

                # Verify deity keyword is present
                deity_token = deity.replace("lord_", "").lower()
                sc_d = sc.get("canonical_deity") or sc.get("deity")
                if sc_d and sc_d != deity:
                    continue
                if deity_token not in prompt and (not avatar or avatar not in prompt):
                    continue

                # Check explicit scene verification status if present
                if sc.get("verification_status") and sc.get("verification_status") not in ("DEITY_VERIFIED", "verified_visual"):
                    continue

                # Strict Provenance Check: If the asset originated from repository collection,
                # it MUST be explicitly approved for this avatar in the index (prevents generic Vishnu / Kurma substitution)
                if source == "repository" or "assets/gods/" in str(img_f).replace("\\", "/"):
                    approved_for_avatar = self.asset_index.find_approved_assets(deity=deity, avatar=avatar)
                    approved_paths = {Path(a.file_path).resolve() for a in approved_for_avatar}
                    if Path(img_f).resolve() not in approved_paths:
                        # Asset is an unverified/mismatched repository file -> REJECT
                        continue

                # Confirm file integrity
                suitable, _ = is_frame_suitable(Path(img_f), min_sharpness_variance=40.0)
                if suitable:
                    return Path(img_f)

            return None
        except Exception:
            return None

    def _attempt_pollinations_fallback(
        self,
        topic: str,
        deity: str,
        avatar: Optional[str],
        timeout: int,
        temp_dir: Path,
    ) -> Optional[Path]:
        """
        Safely calls Pollinations anonymous endpoint with 1 attempt only.
        Fails fast on 402/429 without repeated retries.
        """
        prompt = build_thumbnail_background_prompt(
            topic=topic,
            deity=avatar.title() if avatar else deity.title(),
            thumbnail_title=topic,
        )

        provider = PollinationsProvider(
            model="flux",
            timeout=timeout,
            max_retries=1,  # Strict: no repeated retries when quota exhausted
        )

        out_bg = temp_dir / f"pollinations_fallback_{os.getpid()}.png"
        try:
            provider.generate_background(prompt=prompt, output_path=out_bg, width=1280, height=720)
            if out_bg.exists() and out_bg.stat().st_size > 0:
                suitable, _ = is_frame_suitable(out_bg, min_sharpness_variance=30.0)
                if suitable:
                    return out_bg
            return None
        except (PollinationsError, Exception):
            return None
